```python
import random
import asyncio
from sc2 import maps, Race, Difficulty, run_game, position
from sc2.player import Bot, Computer
from sc2.constants import *
from sc2.bot_ai import BotAI
from sc2.ids.ability_id import AbilityId
from sc2.ids.unit_typeid import UnitTypeId

class StalkerBot(BotAI):
    async def on_step(self, iteration):
        # If no Nexus left, do nothing
        if not self.townhalls:
            return

        await self.distribute_workers()
        await self.build_pylons()
        await self.build_probes()
        await self.build_assimilators()
        await self.build_gateway()
        await self.build_cybercore()
        await self.research_warpgate()
        await self.morph_gateways()
        await self.warp_units()
        await self.build_proxy_pylon()
        await self.chrono_boost()
        await self.attack()

    async def build_pylons(self):
        if self.supply_left < 5 and self.already_pending(PYLON) == 0:
            nex = self.townhalls.ready.random
            pos = nex.position.towards(self.game_info.map_center, 5)
            if self.can_afford(PYLON):
                await self.build(PYLON, near=pos)

    async def build_probes(self):
        for nexus in self.townhalls.ready:
            if self.can_afford(PROBE) and nexus.is_idle and self.workers.amount < self.townhalls.amount * 22:
                nexus.train(PROBE)

    async def build_assimilators(self):
        for nexus in self.townhalls.ready:
            vaspenes = self.vespene_geyser.closer_than(15.0, nexus)
            for vaspene in vaspenes:
                if not self.gas_buildings.closer_than(1.0, vaspene).exists and self.can_afford(ASSIMILATOR):
                    worker = self.select_build_worker(vaspene.position)
                    if worker:
                        worker.build(ASSIMILATOR, vaspene)
                        break

    async def build_gateway(self):
        if self.structures(PYLON).ready.exists and self.structures(GATEWAY).amount + self.structures(WARPGATE).amount < 2:
            pylon = self.structures(PYLON).ready.random
            if self.can_afford(GATEWAY) and self.already_pending(GATEWAY) == 0:
                await self.build(GATEWAY, near=pylon)

    async def build_cybercore(self):
        if self.structures(GATEWAY).ready.exists and not self.structures(CYBERNETICSCORE):
            pylon = self.structures(PYLON).ready.random
            if self.can_afford(CYBERNETICSCORE) and self.already_pending(CYBERNETICSCORE) == 0:
                await self.build(CYBERNETICSCORE, near=pylon)

    async def research_warpgate(self):
        for core in self.structures(CYBERNETICSCORE).ready.idle:
            abilities = await self.get_available_abilities(core)
            if AbilityId.RESEARCH_WARPGATE in abilities and self.can_afford(RESEARCH_WARPGATE):
                core.research(RESEARCH_WARPGATE)

    async def morph_gateways(self):
        if self.structures(CYBERNETICSCORE).ready.exists and self.structures(WARPGATE).amount < self.structures(GATEWAY).ready.amount:
            for gateway in self.structures(GATEWAY).ready.idle:
                abilities = await self.get_available_abilities(gateway)
                if AbilityId.MORPH_WARPGATE in abilities:
                    gateway(AbilityId.MORPH_WARPGATE)

    async def warp_units(self):
        if self.structures(WARPGATE).ready.exists and self.structures(PYLON).ready.exists:
            for warpgate in self.structures(WARPGATE).ready:
                abilities = await self.get_available_abilities(warpgate)
                if AbilityId.WARPGATETRAIN_STALKER in abilities and self.can_afford(STALKER):
                    pylon = self.structures(PYLON).ready.closest_to(self.enemy_start_locations[0])
                    placement = await self.find_placement(AbilityId.WARPGATETRAIN_STALKER, pylon.position, placement_step=1)
                    if placement:
                        warpgate.warp_in(STALKER, placement)

    async def build_proxy_pylon(self):
        if self.structures(PYLON).amount < 3 and self.can_afford(PYLON):
            pos = self.enemy_start_locations[0].towards(self.game_info.map_center, 20)
            if not self.structures(PYLON).closer_than(8, pos).exists:
                await self.build(PYLON, near=pos)

    async def chrono_boost(self):
        for nexus in self.townhalls.ready:
            abilities = await self.get_available_abilities(nexus)
            if AbilityId.EFFECT_CHRONOBOOSTENERGYCOST in abilities:
                # Prioritize Cybercore, then Nexus
                target = None
                if self.structures(CYBERNETICSCORE).ready.exists:
                    core = self.structures(CYBERNETICSCORE).ready.first
                    if core.is_idle is False:
                        target = core
                if not target:
                    target = nexus
                nexus(AbilityId.EFFECT_CHRONOBOOSTENERGYCOST, target)

    async def attack(self):
        stalkers = self.units(STALKER).idle
        if stalkers.exists:
            targets = self.enemy_units
            if targets.exists:
                for stalker in stalkers:
                    stalker.attack(targets.closest_to(stalker))
            else:
                for stalker in stalkers:
                    stalker.attack(self.enemy_start_locations[0])

def main():
    run_game(
        maps.get("(2)CatalystLE"),
        [Bot(Race.Protoss, StalkerBot()), Computer(Race.Protoss, Difficulty.Easy)],
        realtime=False,
    )

if __name__ == "__main__":
    main()
